const lines = $input.first().json.result || [];
const moves = $('Consultar Facturas del Mes').first().json.result || [];
const params = $('Preparar Parametros Busqueda').first().json;

const moveMap = {};
for (const m of moves) {
  moveMap[m.id] = m;
}

let totalBase = 0;
let totalDescAplicado = 0;
let cashbackTeorico5 = 0;
let cashbackReal5 = 0;

let lineasCon2 = 0;
let lineasSinDesc = 0;
let lineasDescAnomalo = 0;

const anomaliasPorFactura = {};
const detalleProductosAnomalos = {};

for (const l of lines) {
  const m = moveMap[l.move_id?.[0]];
  if (!m) continue;

  const qty = Number(l.quantity || 0);
  const price = Number(l.price_unit || 0);
  const base = qty * price;
  const d = Number(l.discount || 0);

  totalBase += base;
  totalDescAplicado += base * (d / 100);
  cashbackTeorico5 += base * 0.05;

  if (Math.abs(d - 2.0) < 0.01) {
    lineasCon2++;
    cashbackReal5 += base * 0.05;
  } else if (d === 0) {
    lineasSinDesc++;
    const invName = m.name || `ID:${m.id}`;
    const partnerName = m.partner_id?.[1] || 'N/D';
    const prodName = l.product_id?.[1] || l.name || 'Producto N/D';

    if (!anomaliasPorFactura[invName]) {
      anomaliasPorFactura[invName] = {
        cliente: partnerName,
        fecha: m.invoice_date,
        sucursal: m.company_id?.[1] || 'N/D',
        lineas: 0,
        basePerdida: 0,
        cbPerdido: 0
      };
    }
    anomaliasPorFactura[invName].lineas++;
    anomaliasPorFactura[invName].basePerdida += base;
    anomaliasPorFactura[invName].cbPerdido += base * 0.05;

    detalleProductosAnomalos[prodName] = (detalleProductosAnomalos[prodName] || 0) + (base * 0.05);
  } else {
    lineasDescAnomalo++;
  }
}

const round2 = n => Math.round((n + Number.EPSILON) * 100) / 100;
const totalAnomalias = lineasSinDesc + lineasDescAnomalo;
const cbEnRiesgo = round2(cashbackTeorico5 - cashbackReal5);

const topFacturas = Object.entries(anomaliasPorFactura)
  .sort((a, b) => b[1].cbPerdido - a[1].cbPerdido)
  .slice(0, 7)
  .map(([inv, d]) => `• <b>${inv}</b> (${d.cliente.split(' ')[0]} / ${d.sucursal.replace('MDS ', '')}): ${d.lineas} líneas 0% ➔ <b>+$${round2(d.cbPerdido).toFixed(2)} CB</b>`);

let text = '';
if (totalAnomalias > 0) {
  text = `⚠️ <b>Auditoría Semanal: Inconsistencias Esquema Cashback (2%+5%)</b>\n` +
    `Periodo: <b>${params.mes_nombre}</b>\n` +
    `Facturas analizadas: <b>${moves.length}</b> · Líneas: <b>${lines.length}</b>\n\n` +
    `📊 <b>Resumen de Cumplimiento:</b>\n` +
    `✅ Líneas con 2% correcto: <b>${lineasCon2}</b> (${lines.length > 0 ? (lineasCon2/lines.length*100).toFixed(1) : 0}%)\n` +
    `❌ Líneas con 0% descuento: <b>${lineasSinDesc}</b>\n` +
    `⚠️ Líneas con desc ≠ 2%: <b>${lineasDescAnomalo}</b>\n\n` +
    `💰 <b>Impacto Financiero de Cashback 5%:</b>\n` +
    `• Provisión Teórica: <b>$${round2(cashbackTeorico5).toFixed(2)} MXN</b>\n` +
    `• Cashback Capturado: <b>$${round2(cashbackReal5).toFixed(2)} MXN</b>\n` +
    `• <b>Cashback No Acumulado (Riesgo): $${cbEnRiesgo.toFixed(2)} MXN</b>\n\n` +
    `📋 <b>Facturas prioritarias a corregir antes del cierre:</b>\n${topFacturas.join('\n')}\n\n` +
    `<i>Acción requerida: Revisar y ajustar el 2% por línea en las facturas listadas para asegurar la correcta bonificación a fin de mes.</i>`;
} else {
  text = `✅ <b>Auditoría Semanal: Esquema Cashback (2%+5%) al 100%</b>\n` +
    `Periodo: <b>${params.mes_nombre}</b>\n` +
    `Facturas analizadas: <b>${moves.length}</b> · Líneas: <b>${lines.length}</b>\n` +
    `Todas las líneas de los clientes del esquema cuentan con el 2% aplicado correctamente.\n` +
    `Provisión acumulada: <b>$${round2(cashbackReal5).toFixed(2)} MXN</b>`;
}

return [{
  json: {
    text,
    total_anomalias: totalAnomalias,
    cb_en_riesgo: cbEnRiesgo,
    total_facturas: moves.length
  }
}];

